=== usb_serial.ino ===
   1| // Button toggles LED and prints the new state
   2| 
   3| const int button = 2;
   4| const int led = LED_BUILTIN;
   5| 
   6| int lastStable = HIGH;
   7| int lastRaw = HIGH;
   8| unsigned long rawChangedMs = 0;
   9| bool isOn = false;
  10| 
  11| void setup() {
  12|   pinMode(button, INPUT_PULLUP);
  13|   pinMode(led, OUTPUT);
  14|   digitalWrite(led, LOW);
  15|   Serial.begin(9600);
  16| }
  17| 
  18| void loop() {
  19|   int raw = digitalRead(button);
  20|   if (raw != lastRaw) {
  21|     rawChangedMs = millis();
  22|     lastRaw = raw;
  23|   }
  24|   if (millis() - rawChangedMs >= 5 && raw != lastStable) {
  25|     lastStable = raw;
  26|     if (raw == LOW) {
  27|       isOn = !isOn;
  28|       digitalWrite(led, isOn);
  29|       Serial.println(isOn ? "ON" : "OFF");
  30|     }
  31|   }
  32| }
</student_code>
